function draw(ctx, state, t) {
  var top = 36;
  var bot = 286;
  var left = 48;
  var right = 560;
  var mid = 161;
  var m = state.m;
  var base = state.base;
  var ang = state.ang;
  function fmt(v) { return Math.round(v * 100) / 100; }
  function scoreAt(d, th) { return Math.cos(d * th); }
  var theta = ang * 10000 / base;
  if (theta < 0.01) { theta = 0.01; }
  var thr = 0;
  var ythr = mid;
  var i = 0;
  var n = 32;
  var d = 0;
  var x = 0;
  var y = 0;
  var s = 0;
  ctx.clearRect(0, 0, state.w, state.h);
  ctx.fillStyle = "#f6f3ec";
  ctx.fillRect(0, 0, state.w, state.h);
  ctx.strokeStyle = "#1f4b99";
  ctx.lineWidth = 1;
  ctx.strokeRect(left, top, right - left, bot - top);
  ctx.beginPath();
  ctx.moveTo(left, ythr);
  ctx.lineTo(right, ythr);
  ctx.stroke();
  ctx.strokeStyle = "#1f4b99";
  ctx.lineWidth = 2;
  ctx.beginPath();
  for (i = 0; i <= n; i++) {
    d = i * 16 / n;
    s = scoreAt(d, theta);
    x = left + d * (right - left) / 16;
    y = mid - s * 100;
    if (i === 0) { ctx.moveTo(x, y); } else { ctx.lineTo(x, y); }
  }
  ctx.stroke();
  var xm = left + m * (right - left) / 16;
  var sm = scoreAt(m, theta);
  var ym = mid - sm * 100;
  ctx.fillStyle = "#c4512c";
  ctx.beginPath();
  ctx.arc(xm, ym, 5, 0, Math.PI * 2);
  ctx.fill();
  var cx = 120;
  var cy = 90;
  var r = 32;
  var a = m * theta;
  var qx = cx + Math.cos(a) * r;
  var qy = cy - Math.sin(a) * r;
  ctx.strokeStyle = "#1f4b99";
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(cx, cy);
  ctx.lineTo(qx, qy);
  ctx.stroke();
  ctx.fillStyle = "#c4512c";
  ctx.beginPath();
  ctx.arc(qx, qy, 4, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = "#1f4b99";
  ctx.font = "12px sans-serif";
  ctx.fillText("threshold " + fmt(thr), left, ythr - 8);
  ctx.fillText("score = " + fmt(sm) + " at m = " + fmt(m), 48, 318);
  ctx.fillText("toy theta = " + fmt(theta), 48, 344);
}
